module.constraint:
eval('
' + ' var break_field_bits = ${module.driver.sci_lin.break_field_bits}; 
' + ' var delimiter_bits = ${module.driver.sci_lin.delimiter_bits}; 
' + ' var baud = ${module.driver.sci_lin.baud}; 
' + ' freq_hz = ${board.clock.peripheral.sci}; 
' + ' var timer_div = "${module.driver.sci_lin.timer_div}"; 
' + ' var lin_divider = 1; 
' + ' if ("module.driver.sci_lin.timer_div.div_2" === timer_div) { 
' + ' lin_divider = 2; 
' + ' } 
' + ' else if ("module.driver.sci_lin.timer_div.div_4" === timer_div) { 
' + ' lin_divider = 4; 
' + ' } 
' + ' else if ("module.driver.sci_lin.timer_div.div_8" === timer_div) { 
' + ' lin_divider = 8; 
' + ' } 
' + ' else if ("module.driver.sci_lin.timer_div.div_16" === timer_div) { 
' + ' lin_divider = 16; 
' + ' } 
' + ' else if ("module.driver.sci_lin.timer_div.div_32" === timer_div) { 
' + ' lin_divider = 32; 
' + ' } 
' + ' else if ("module.driver.sci_lin.timer_div.div_64" === timer_div) { 
' + ' lin_divider = 64; 
' + ' } 
' + ' else if ("module.driver.sci_lin.timer_div.div_128" === timer_div) { 
' + ' lin_divider = 128; 
' + ' } 
' + 'var lin_timer_hz = freq_hz / lin_divider; 
' + 'var output = null; 
' + 'var break_field_setting = Math.floor( (lin_timer_hz * break_field_bits) / ( baud ) ); 
' + 'var break_delimiter_setting = Math.floor( (lin_timer_hz * delimiter_bits) / ( baud ) ); 
' + 'var max = 0xffff; 
' + 'if (break_field_setting > max) { 
' + 'output = " LIN timer break field width/threshold setting exceeds maximum (65535).\n Break Field Length = ( ( PCLK / (LIN Timer Divider) * (Break Field Bits) ) / (Baud Rate) ) \n = ( ( (" + freq_hz + "/" + lin_divider + ") *" + break_field_bits + ") / (" + baud + ") ) = " + break_field_setting + "\n Adjust LIN source clock, divider, break field bits, or baud rate."; 
' + '} 
' + 'if (break_delimiter_setting > max) { 
' + 'output = " LIN timer break delimiter setting exceeds maximum (65535).\n Break Delimiter Length = ( ( PCLK / (LIN Timer Divider) * (Break Delimiter Bits) ) / (Baud Rate) ) \n = ( ( (" + freq_hz + "/" + lin_divider + ") *" + delimiter_bits + ") / (" + baud + ") ) = " + break_delimiter_setting + "\n Adjust LIN source clock, divider, break delimiter bits, or baud rate."; 
' + '} 
' + 'output')

property.export:
eval('' + ' /* INPUTS BAUDRATE */' + ' var freq_hz = ${board.clock.peripheral.sci};' + ' var baudrate = ${module.driver.sci_lin.baud};' + ' var baseclock = ("SCI_LIN_BASE_CLOCK_8" === "${module.driver.sci_lin.base_clock_select}") ? 1 : 0;' + ' /* BRR Max */' + ' var SCI_LIN_BRR_MAX = 255;' + ' /* CKS Max */' + ' var SCI_LIN_CKS_MAX = 3;' + ' /* Baud divisor shift Min */' + ' var SCI_LIN_MIN_BAUD_DIVISOR_SHIFT = 5;' + '/*******************************************************************************************************************//**
' + ' * Calculates baud rate register settings based on internal clock frequency. Evaluates and determines the best possible
' + ' * settings set to the baud rate related registers. Ported from R_SCI_LIN_BaudCalculate.
' + ' *' + ' * @param[in] freq_hz The source clock frequency for the SCI internal clock
' + ' * @param[in] baudrate Baud rate [bps] e.g. 19200, 57600, 115200, etc.
' + ' *' + ' * @return {brr, Value for the BRR
' + ' * baud_setting, Baud settings: {bgdm, abcs, abcse, cks}
' + ' * brr_error, % bit rate error
' + ' * actual_baud_rate, Value of actual baudrate
' + ' **********************************************************************************************************************/' + 'function r_sci_lin_brr_calculate(freq_hz, baudrate){
' + ' var divisor = 0;
' + ' var brr = 0;
' + ' var cks = -1;
' + ' /* BGDM is helpful for achieving high bitrates, but LIN is very low speed, it is able to easily achieve all required bitrates without using BGDM.' + ' * BGDM should be set to 0. */
' + ' var bgdm = 0;
' + ' var divisor_shift;
' + ' var result = {brr: 0, baud_setting: {bgdm:0, abcs:0, abcse:0, cks:0}, brr_error: 100, actual_baud_rate: 0};
' + ' /* BRR is calculated by testing whether each divisor (combination of BGDM, ABCS, CKS, and N) produces a valid BRR setting.' + ' * The divisors are checked in order, from smallest to largest. The smallest divisor always produces the lowest error for a given theoretical rate. */
' + ' for (var i = 0; i <= SCI_LIN_CKS_MAX; i++)' + ' {' + ' cks++;' + ' divisor_shift = SCI_LIN_MIN_BAUD_DIVISOR_SHIFT + (cks << 1) - (bgdm + baseclock);' + ' divisor = (1 << divisor_shift) * baudrate;' + ' brr = Math.floor((freq_hz / divisor) - 1);' + ' /* If calculation succeeded */' + ' if (brr <= SCI_LIN_BRR_MAX)' + ' {' + ' /* Calculate the error at this baud rate */' + ' var err_divider = (divisor * (brr + 1));' + ' var bit_err = Math.abs((((freq_hz * 100) / err_divider) - 100));' + ' /* Save the best settings*/' + ' result.baud_setting = { bgdm: bgdm, abcs: baseclock, abcse: 0 , cks: cks };' + ' result.brr = brr;' + ' result.brr_error = bit_err;' + ' result.actual_baud_rate = freq_hz / ((1 << divisor_shift) * (brr + 1));' + ' return result; // Exit function when first valid result is found
' + ' }' + ' }
' + ' return result;
' + '}
' + '' + '/* INPUTS Break Field Length */' + '/* Calculate "lin_timer_hz" and "break_bits" */' + ' var break_bits = ${module.driver.sci_lin.break_field_bits};' + ' var timer_div = "${module.driver.sci_lin.timer_div}";' + ' var lin_divider_settings = [' + ' { value: 1, name: "SCI_LIN_TIMER_DIV_1" },' + ' { value: 2, name: "SCI_LIN_TIMER_DIV_2" },' + ' { value: 4, name: "SCI_LIN_TIMER_DIV_4" },' + ' { value: 8, name: "SCI_LIN_TIMER_DIV_8" },' + ' { value: 16, name: "SCI_LIN_TIMER_DIV_16" },' + ' { value: 32, name: "SCI_LIN_TIMER_DIV_32" },' + ' { value: 64, name: "SCI_LIN_TIMER_DIV_64" },' + ' { value: 128, name: "SCI_LIN_TIMER_DIV_128"},' + ' ];
' + ' var lin_divider = 1;
'+ // Initialize lin_divider to a default value ' for (var i = 0, len = lin_divider_settings.length; i < len; i++){
 ' + ' if (lin_divider_settings[i].name === timer_div) {
' + ' lin_divider = lin_divider_settings[i].value;
' + // Assign only when condition matches ' break;' + ' }' + ' }' + ' var lin_timer_hz = freq_hz / lin_divider; 
' + ' var break_delimiter_bits = ${module.driver.sci_lin.delimiter_bits};' + '' + '/**************************************************************************************************************************//**' + ' * Calculates LIN break field width register setting based on internal clock frequency and desired break field length in bits. ' + ' * The LIN timer is used for break field detection and generation.' + ' *' + ' * @param[in] baudrate Baud rate[bps] e.g. 9600, 19200, etc.' + ' * @param[in] break_bits Number of dominant break field bits (e.g., 9, 13, 18)' + ' * @param[in] break_delimiter_bits Number of dominant break delimiter bits (e.g., 1, 2)' + ' *' + ' * @return break_field_tpre Value for the TPRE counter of Break Field setting' + ' * @return break_field_tcnt Value for the TNCT counter of Field setting' + ' * @return delimiter_tpre Value for the TPRE counter of Break Delimiter setting' + ' * @return delimiter_tcnt Value for the TNCT counter of Break Delimiter setting' + ' *****************************************************************************************************************************/' + 'function r_sci_lin_break_field_calculate(baudrate, break_bits, break_delimiter_bits) {
' + ' var break_field_setting = Math.floor((lin_timer_hz * break_bits) / baudrate);
' + // Calculate Break Field Length setting ' var break_delimiter_setting = Math.floor((lin_timer_hz * break_delimiter_bits) / baudrate);
' + // Calculate Break delimiter setting ' var break_field_tcnt = (break_field_setting >> 8) & 0xFF;' + ' var break_field_tpre = Math.floor(((break_field_setting + break_field_tcnt) / (break_field_tcnt + 1)) - 1);' + ' var delimiter_tcnt = (break_delimiter_setting >> 8) & 0xFF;' + ' var delimiter_tpre = Math.floor(((break_delimiter_setting + delimiter_tcnt)/ (delimiter_tcnt + 1)) - 1);' + ' return {' + ' break_field_tcnt: break_field_tcnt,' + ' break_field_tpre: break_field_tpre,' + ' delimiter_tcnt: delimiter_tcnt,' + ' delimiter_tpre: delimiter_tpre,' + ' };
' + '}' + '' + '/* Calculate baud rate register settings */
' + 'var baud_result = r_sci_lin_brr_calculate(freq_hz, baudrate);
' + '' + '/* Compute Break Field and Break Delimiter settings at this baud rate */' + ' var break_field_result = r_sci_lin_break_field_calculate(baudrate, break_bits, break_delimiter_bits);' + '' + '/* RESULT */
' + 'var c_baud_setting = "/* Actual calculated baud rate: " + baud_result.actual_baud_rate.toFixed(0) + " (" + baud_result.brr_error.toFixed(3) + "% error) */" +
' + ' " .semr_baudrate_bits_b = { .abcse = " + baud_result.baud_setting.abcse.toString() +
' + ' ", .abcs = " + baud_result.baud_setting.abcs.toString() +
' + ' ", .bgdm = " + baud_result.baud_setting.bgdm.toString() +
' + ' "}, .cks = " + baud_result.baud_setting.cks.toString() +' + ' ", .brr = " + baud_result.brr.toString() +' + ' ", .timer_setting = { .tcss = " + "${module.driver.sci_lin.timer_div}" +' + ' ", .break_field_tpre = " + break_field_result.break_field_tpre.toString() +' + ' ", .break_field_tcnt = " + break_field_result.break_field_tcnt.toString() +' + ' ", .delimiter_tpre = " + break_field_result.delimiter_tpre +' + ' ", .delimiter_tcnt = " + break_field_result.delimiter_tcnt + "}";' + '/* Output the C baud setting structure */
' + 'c_baud_setting;' +
'')

module.header:
            /** LIN on SCI Instance. */
            extern const lin_instance_t ${module.driver.sci_lin.name};

            /** Access the LIN instance using these structures when calling API functions directly
            (::p_api is not used). */
            extern sci_lin_instance_ctrl_t ${module.driver.sci_lin.name}_ctrl;
            extern const lin_cfg_t ${module.driver.sci_lin.name}_cfg;
            extern const sci_lin_extended_cfg_t ${module.driver.sci_lin.name}_cfg_extend;

#ifndef ${module.driver.sci_lin.callback}
            void ${module.driver.sci_lin.callback}(lin_callback_args_t * p_args);
#endif

module.declarations:
sci_lin_instance_ctrl_t ${module.driver.sci_lin.name}_ctrl;
/** LIN extended configuration for LIN on SCI HAL driver */ const sci_lin_extended_cfg_t ${module.driver.sci_lin.name}_cfg_extend = { .digital_filter_clock = ${module.driver.sci_lin.digital_filer_clock}, .bus_conflict_clock = ${module.driver.sci_lin.bus_conflict_clock}, .break_bits = ${module.driver.sci_lin.break_field_bits}, .delimiter_bits = ${module.driver.sci_lin.delimiter_bits},
/* Baud-rate setting */ .baud_setting = { ${module.driver.sci_lin.baud}, },
/* ID filter setting */ .filter_setting = { .compare_data_mask = ${module.driver.sci_lin.compare_data_mask}, .primary_compare_data = ${module.driver.sci_lin.primary_compare_data}, .secondary_compare_data = ${module.driver.sci_lin.secondary_compare_data}, .priority_interrupt_bit_select = ${module.driver.sci_lin.priority_interrupt_bit_select}, .priority_interrupt_enable = ${module.driver.sci_lin.priority_interrupt_enable}, .compare_data_select = ${module.driver.sci_lin.compare_data_select}, }, /* Interrupt settings */ .scix0_ipl = ${module.driver.sci_lin.scix0_ipl}, .scix1_ipl = ${module.driver.sci_lin.scix1_ipl}, .scix2_ipl = ${module.driver.sci_lin.scix2_ipl}, .rxi_ipl = ${module.driver.sci_lin.rxi_ipl}, .txi_ipl = ${module.driver.sci_lin.txi_ipl}, .tei_ipl = ${module.driver.sci_lin.tei_ipl}, .eri_ipl = ${module.driver.sci_lin.eri_ipl}, #if defined(VECTOR_NUMBER_SCI${module.driver.sci_lin.channel}_SCIX0) .scix0_irq = VECTOR_NUMBER_SCI${module.driver.sci_lin.channel}_SCIX0, #else .scix0_irq = FSP_INVALID_VECTOR, #endif #if defined(VECTOR_NUMBER_SCI${module.driver.sci_lin.channel}_SCIX1) .scix1_irq = VECTOR_NUMBER_SCI${module.driver.sci_lin.channel}_SCIX1, #else .scix1_irq = FSP_INVALID_VECTOR, #endif #if defined(VECTOR_NUMBER_SCI${module.driver.sci_lin.channel}_SCIX2) .scix2_irq = VECTOR_NUMBER_SCI${module.driver.sci_lin.channel}_SCIX2, #else .scix2_irq = FSP_INVALID_VECTOR, #endif #if defined(VECTOR_NUMBER_SCI${module.driver.sci_lin.channel}_RXI) .rxi_irq = VECTOR_NUMBER_SCI${module.driver.sci_lin.channel}_RXI, #else .rxi_irq = FSP_INVALID_VECTOR, #endif #if defined(VECTOR_NUMBER_SCI${module.driver.sci_lin.channel}_TXI) .txi_irq = VECTOR_NUMBER_SCI${module.driver.sci_lin.channel}_TXI, #else .txi_irq = FSP_INVALID_VECTOR, #endif #if defined(VECTOR_NUMBER_SCI${module.driver.sci_lin.channel}_TEI) .tei_irq = VECTOR_NUMBER_SCI${module.driver.sci_lin.channel}_TEI, #else .tei_irq = FSP_INVALID_VECTOR, #endif #if defined(VECTOR_NUMBER_SCI${module.driver.sci_lin.channel}_ERI) .eri_irq = VECTOR_NUMBER_SCI${module.driver.sci_lin.channel}_ERI #else .eri_irq = FSP_INVALID_VECTOR #endif };
/** LIN interface configuration */ const lin_cfg_t ${module.driver.sci_lin.name}_cfg = { .channel = ${module.driver.sci_lin.channel}, .mode = ${module.driver.sci_lin.mode}, .p_callback = ${module.driver.sci_lin.callback}, .p_context = NULL, .p_extend = &${module.driver.sci_lin.name}_cfg_extend, };
/* Instance structure to use this module. */ const lin_instance_t ${module.driver.sci_lin.name} = { .p_ctrl = &${module.driver.sci_lin.name}_ctrl, .p_cfg = &${module.driver.sci_lin.name}_cfg, .p_api = &g_lin_on_sci };

